TLM.f("Tempora/Epi5-5",{"officium":"Feria VI infra Hebdomadam V post Epiphaniam","rule":["vide Epi5-0","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate"],"fallback":"Tempora/Epi5-0","from":{"Introitus":"Tempora/Epi5-0","Oratio":"Tempora/Epi5-0","Lectio":"Tempora/Epi5-0","Graduale":"Tempora/Epi5-0","Evangelium":"Tempora/Epi5-0","Offertorium":"Tempora/Epi5-0","Secreta":"Tempora/Epi5-0","Communio":"Tempora/Epi5-0","Postcommunio":"Tempora/Epi5-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 96:7-8"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Adoráte Deum, omnes Angeli ejus: audívit, et lætáta est Sion: et exsultavérunt fíliæ Judæ."}],"Oratio":[{"k":"text","la":"Famíliam tuam, quǽsumus, Dómine, contínua pietáte custódi: ut, quæ in sola spe grátiæ cœléstis innítitur, tua semper protectióne muniátur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses"},{"k":"ref","la":"Col 3:12-17"},{"k":"text","la":"Fratres: Indúite vos sicut elécti Dei, sancti et dilécti, víscera misericórdiæ, benignitátem, humilitátem, modéstiam, patiéntiam: supportántes ínvicem, et donántes vobismetípsis, si quis advérsus áliquem habet querélam: sicut et Dóminus donávit vobis, ita et vos. Super ómnia autem hæc caritátem habéte, quod est vínculum perfectiónis: et pax Christi exsúltet in córdibus vestris, in qua et vocáti estis in uno córpore: et grati estóte. Verbum Christi hábitet in vobis abundánter, in omni sapiéntia, docéntes et commonéntes vosmetípsos psalmis, hymnis et cánticis spirituálibus, in grátia cantántes in córdibus vestris Deo. Omne, quodcúmque fácitis in verbo aut in ópere, ómnia in nómine Dómini Jesu Christi, grátias agéntes Deo et Patri per ipsum."}],"Graduale":[{"k":"ref","la":"Ps 101:16-17"},{"k":"text","la":"Timébunt gentes nomen tuum, Dómine, et omnes reges terræ glóriam tuam."},{"k":"text","la":"Quóniam ædificávit Dóminus Sion, et vidébitur in majestáte sua. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 96:1"},{"k":"text","la":"Dóminus regnávit, exsúltet terra: læténtur ínsulæ multæ. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 13:24-30"},{"k":"text","la":"In illo témpore: Dixit Jesus turbis parábolam hanc: Símile factum est regnum cœlórum hómini, qui seminávit bonum semen in agro suo. Cum autem dormírent hómines, venit inimícus ejus, et superseminávit zizánia in médio trítici, et ábiit. Cum autem crevísset herba et fructum fecísset, tunc apparuérunt et zizánia. Accedéntes autem servi patrisfamílias, dixérunt ei: Dómine, nonne bonum semen seminásti in agro tuo? Unde ergo habet zizánia? Et ait illis: Inimícus homo hoc fecit. Servi autem dixérunt ei: Vis, imus, et collígimus ea? Et ait: Non: ne forte colligéntes zizánia eradicétis simul cum eis et tríticum. Sínite utráque créscere usque ad messem, et in témpore messis dicam messóribus: Collígite primum zizánia, et alligáte ea in fascículos ad comburéndum, tríticum autem congregáte in hórreum meum."}],"Offertorium":[{"k":"ref","la":"Ps 117:16; 117:17"},{"k":"text","la":"Déxtera Dómini fecit virtutem, déxtera Dómini exaltávit me: non móriar, sed vivam, et narrábo ópera Dómini."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, placatiónis offérimus: ut et delícta nostra miserátus absólvas, et nutántia corda tu dírigas."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 4:22"},{"k":"text","la":"Mirabántur omnes de his, quæ procedébant de ore Dei."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut illíus salutáris capiámus efféctum, cujus per hæc mystéria pignus accépimus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5e22ba60d4b44e32":{"t":"Ps 96, 7-8, Ps 96, 1\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri. (Ps 96, 1) Gospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 96, 7-8) Klanjajte se Bogu svi anđeli njegovi! Čuje Sion i raduje se, veselo pjevaju sve Judine kćeri.","kn":"(Ps. 96, 7, 8). Klanjaju se Bogu svi anđeli njegovi; čuje i veseli se Slon, i klikću kćeri izabranog naroda. (Ps. 96, 1) Gospodin kraljuje, neka klikće zemlja, neka se vesele brojni otoci! Slava Ocu . . . Klanjaju . . .","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"1f593f0de7c850c0":{"t":"<i>Pomolimo se</i>.\nČuvaj, molimo, Gospodine, svoju obitelj neprestano očinskom dobrotom, da ona, kojoj je jedina nada u nebeskoj milosti, uživa vazda tvoju zaštitu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Čuvaj, molimo. Gospodine, obitelj .svoju neprestanim pomilovanjem,.. pa jer se oslanja samo na nadu nebeskih milosti, zaštićuj je vazda svojim okriljem,. ;PO G. n. I. K. ,, ,","knRef":"Kniewald 1942, str. 436–437 (snimka 219) (OCR)"},"3a77ec4b1e9c3b41":{"t":"Kol 3, 12-17\nČitanje Poslanice bl. Pavla apostola Kološanima. Braćo: kao Božji odabranici, sveti i ljubljeni, budite od srca milosrdni, blagi, ponizni, čedni, strpljivi. Podnosite jedan drugoga i opraštajte jedan drugome, ako se tko ima potužiti na drugoga. Kao što je Gospodin vama oprostio, tako i vi opraštajte. Nadasve imajte ljubav koja je veza savršenstva. I Kristov mir, na koji ste pozvani, neka u vašim srcima vlada kao u jednom tijelu. – Budite i zahvalni! Kristova riječ neka obilno stanuje u vama, u svakoj mudrosti. Poučavajte i potičite jedan drugoga psalmima, himnima, duhovnim pjesmama, na poticaj milosti pjevajte Bogu u svojim srcima. Sve što god govorite i činite neka bude u ime Gospodina Isusa Krista zahvaljujući Bogu Ocu po njemu.","kn":"Čitanje poslanice bi. Pavla apostola Kološanima (3, 12-17). Braćo! Kao Božji izabranici, sveti i ljubljeni, budite od srca milosrdni, blagi, ponizni, čedni, strpljivi. Podnosite jedan drugoga, i kao što je i Gospodin vama oprostio, tako i vi praštajte jedan drugomu, ako tko ima kakvu tužbu protiv drugOiga. Nada sve pak imajte ljubav, koja je veza savršenstva. I Kristov mir, na koji ste pozvani, neka zavlada u vašim srcima kao u jednom tijelu. Budite i zahvalni! Kristova riječ neka se u vama nastani obilno, u svakoj mudrosti, da se učite 1 opominjete jedan drugoga psalmima, himnima i duhovnim pjesmama zahvalno pjevajući Bogu u Evojim srcima, I sve štogod govorite ili činite, sve neka bude u ime Gospodina Isusa Krista zahvaljujući Bogu i Ocu po njemu.","knRef":"Kniewald 1942, str. 84–85 (snimka 43) (OCR)"},"30e75e455763b37f":{"t":"Ps 101, 16-17\nBojat će se narodi imena tvojega, Gospodine, i tvoje slave svi kraljevi zemlje. Jer je Gospodin sagradio Sion i objavit će se u svojem veličanstvu.\n\nPs 96, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nGospodin kraljuje, neka kliče zemlja, neka se raduju mnogi otoci. <i>Aleluja</i>.","kn":"(Ps. 101, 16, 17). Narodi će štovati ime Tvoje, Gospodine, i svi kraljevi zemaljski slavu Tvoju, kad Gospod sagradi Sion i javi se u slavi svojoj. Aleluja, aleluja. (Ps. 96, 1) Gospodin, kraljuje, neka klikće zemlja, neka se vesele brojni otoci! Aleluja.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"790fad0541adc55a":{"t":"Mt 13, 24-30\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Reče Isus narodu ovu usporedbu: Kraljevstvo je nebesko kao čovjek koji na svojoj njivi posije dobro sjeme. Ali kad su ljudi zaspali, dođe njegov neprijatelj, pa među pšenicu posije kukolj i otiđe. A kad usjev izraste i učini klas, pokaže se kukolj. I pristupe sluge domaćinu te mu rekoše: Gospodaru, zar nisi dobro sjeme posijao na svojoj njivi. Pa odakle kukolj? On im odgovori To je učinio neki neprijatelj. Sluge mu rekoše: Hoćeš li da odemo i da ga iščupamo? Odgovori: Ne, da ne biste čupajući kukolj iščupali zajedno i pšenicu. Pustite, nek' oboje raste do žetve! U vrijeme žetve reći ću žeteocima: Pokupite najprije kukolj i svežite ga u snopove da se spali, a pšenicu skupite u moju žitnicu.","kn":"t Slijedi sveto evanđelje Po Mateju (13, 24-30). U ono vrijeme reče. Isus narodu ovu prispodobu: Nebesko je kraljevstvo kao čovjek, koji sije dobro Sjeme na svojoj njivi. Kad su ljudi zaspali, dođe njegov neprijatelj, P'osija kukolj po. pšenici i otide. A kad usjev uzraste i donese plod, pokaza se tada i kukolj. I dođoše gospodarevi sluge i rekoše mu; Gospodaru, zar' ti nijesi posijao dobro sjeme na svojoj njivi? Otkuda, dakle kukolj? A on im reče. To je učinio neprijatelj. Tada ga sluge upitaše; Hoćeš li, da idemo i da ga poberemo? Odgovoi-i im: Ne, da ne bi sabiruči kukolj iščupali zajedno i pšenicu. Pustite da oboje raste do žetve, a u vrijeme žetve reći ću žeteocima: Poberite najprije kukclj i vežite ga u snopove, da se spali, a pšenicu skupite u moju žitnicu!","knRef":"Kniewald 1942, str. 84–85 (snimka 43) (OCR)"},"a63cb5f96fa870c3":{"t":"Ps 117, 16-17\nDesnica Gospodnja učini čudo, desnica me Gospodnja podiže! Neću umrijeti nego živjeti i naviještati djela Gospodnja.","kn":"(Ps. 117, 16, 17). Desnica Gospodnja poka,za moć, desnica me Gospo'dnja uzvisi: ne ću umrijeti, nego živjeti i kazivat ću djela Gospodnjem","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"1c8e508485aa2b6d":{"t":"Prinosimo ti, Gospodine, pomirnu žrtvu da nam milosrdno oprostiš grijehe i da kolebljiva srca vodiš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prinosimo Ti, Gospodine, žrtvu pomirnicu, da nam u svom smilovanju oprostiš naša zlodjela i srca, koja se kolebaju, da Ti upravljaš, po G. n. Predslovlje presvetog Trojstva.","knRef":"Kniewald 1942, str. 438–439 (snimka 220) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"d63bef8a01a22821":{"t":"Lk 4, 22\nSvi su se divili riječima koje su izlazile iz Božjih usta.","kn":"(Lk. 4, 22). Svi su se divili riječima, koje su izlazile iz ustiju Božjih.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"6c7409b64a825e73":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da postignemo ono spasenje, kojega smo zalog primili u ovim otajstvima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, svemogući Bože, da doista postignemo spasenje, kojega smo zalog primili u ovim otajstvima, po G. nr I. K.","knRef":"Kniewald 1942, str. 438–439 (snimka 220) (OCR)"}}});
